import java.nio.file.*;
import java.net.*;
import java.util.*;
import org.simplepoint.platform.bootstrap.registry.migration.*;
import org.simplepoint.platform.dictionary.registration.*;
import org.simplepoint.plugin.rbac.tenant.service.initialize.*;
import org.simplepoint.remoting.RemoteContract;
import org.simplepoint.remoting.RemoteProvider;
import org.springframework.transaction.annotation.Transactional;

public class VerifyInstallationPortsArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyInstallationPortsArtifacts.class.getClassLoader();
    for (Class<?> type : List.of(BootstrapLegacyTransfer.class, BootstrapLegacyTransferPort.class,
        BootstrapLegacyTransferAdapter.class, DictionaryLegacyAdoptionPort.class,
        DictionaryLegacyAdoptionAdapter.class)) {
      if (Collections.list(loader.getResources(type.getName().replace('.', '/') + ".class")).size() != 1)
        throw new AssertionError("Duplicate or missing installed class: " + type.getName());
      if (type.isAnnotationPresent(RemoteContract.class) || type.isAnnotationPresent(RemoteProvider.class))
        throw new AssertionError("Privileged installation port leaked to RPC");
    }
    if (!BootstrapLegacyTransferPort.class.isAssignableFrom(BootstrapLegacyTransferAdapter.class)
        || !DictionaryLegacyAdoptionPort.class.isAssignableFrom(DictionaryLegacyAdoptionAdapter.class))
      throw new AssertionError("Domain port bindings missing");
    for (var method : List.of(
        BootstrapLegacyTransfers.class.getMethod("findCompletion", BootstrapLegacyTransfer.Identity.class),
        DictionaryLegacyAdoptions.class.getMethod("findCompletion", String.class))) {
      var tx = method.getAnnotation(Transactional.class);
      if (tx == null || !tx.readOnly()) throw new AssertionError("Lost owner read transaction");
    }
    var paths = List.of(
        "simplepoint-platform/simplepoint-platform-installation-dictionary/build/libs/simplepoint-platform-installation-dictionary.jar",
        "simplepoint-platform/simplepoint-platform-installation/build/libs/simplepoint-platform-installation.jar",
        "simplepoint-platform/simplepoint-platform-bootstrap-registry-api/build/libs/simplepoint-platform-bootstrap-registry-api.jar",
        "simplepoint-platform/simplepoint-platform-dictionary-registration/build/libs/simplepoint-platform-dictionary-registration.jar",
        "simplepoint-platform/simplepoint-platform-dictionary-api/build/libs/simplepoint-platform-dictionary-api.jar",
        "simplepoint-platform/simplepoint-platform-composition/build/libs/simplepoint-platform-composition.jar",
        "simplepoint-remoting/simplepoint-remoting-core/build/libs/simplepoint-remoting-core.jar");
    var urls = new ArrayList<URL>();
    for (String path : paths) urls.add(Path.of(path).toUri().toURL());
    try (var pure = new URLClassLoader(urls.toArray(URL[]::new), ClassLoader.getPlatformClassLoader())) {
      var source = pure.loadClass(BootstrapLegacyTransferPort.class.getName());
      var target = pure.loadClass(DictionaryLegacyAdoptionPort.class.getName());
      var bridge = pure.loadClass("org.simplepoint.platform.installation.dictionary.DictionaryAdoptionInstallation");
      bridge.getConstructor(source, target);
      bridge.getDeclaredMethods();
      for (String forbidden : List.of("org.springframework.context.ApplicationContext", "jakarta.persistence.EntityManager",
          "com.rabbitmq.client.ConnectionFactory", BootstrapLegacyTransfers.class.getName(), DictionaryLegacyAdoptions.class.getName())) {
        try { pure.loadClass(forbidden); throw new AssertionError("Impure installer runtime: " + forbidden); }
        catch (ClassNotFoundException expected) { }
      }
    }
    System.out.println("Verified installed pure DTO uniqueness, non-RPC domain port bindings and retained read-only transactions; isolated installer JAR classloader loads the adapter without Spring/JPA/broker/domain implementations.");
  }
}
